Class Product
  Define name As String;
  Define price As Integer;

  Method Constructor(productName As String, productPrice As Integer)
    This.name <- productName;
    This.price <- productPrice;
  EndMethod

  Method Amount(quantity As Integer) As Integer
    Return This.price * quantity;
  EndMethod
EndClass

Class Inventory
  Private Define stock As Dictionary<String, Integer>;

  Method Constructor()
    This.stock <- dictionary();
  EndMethod

  Method Load(name As String, quantity As Integer)
    This.stock[name] <- quantity;
  EndMethod

  Method Withdraw(name As String, quantity As Integer) As Boolean
    If quantity > This.stock[name] Then
      Return False;
    EndIf
    This.stock[name] <- This.stock[name] - quantity;
    Return True;
  EndMethod
EndClass

Class Receipt
  Private Define lines As Vector<String>;

  Method Constructor()
    This.lines <- vector();
  EndMethod

  Method Note(line As String)
    This.lines.append(line);
  EndMethod

  Method Display()
    For Each line In This.lines Do
      Write line;
    EndFor
  EndMethod
EndClass

Class Till
  Private Define total As Integer;

  Method Constructor()
    This.total <- 0;
  EndMethod

  Method Sell(product As Product, quantity As Integer, inventory As Inventory, receipt As Receipt)
    If inventory.Withdraw(product.name, quantity) Then
      This.total <- This.total + product.Amount(quantity);
      receipt.Note(product.name + " x " + toText(quantity) + " = " + toText(product.Amount(quantity)));
    Else
      receipt.Note(product.name + " x " + toText(quantity) + " rejected");
    EndIf
  EndMethod

  Method Total() As Integer
    Return This.total;
  EndMethod
EndClass

Algorithm Kiosk
  Define juice As Product <- New Product("Juice", 3);
  Define sandwich As Product <- New Product("Sandwich", 5);
  Define inventory As Inventory <- New Inventory();
  inventory.Load("Juice", 10);
  inventory.Load("Sandwich", 5);
  Define receipt As Receipt <- New Receipt();
  Define till As Till <- New Till();
  till.Sell(juice, 3, inventory, receipt);
  till.Sell(sandwich, 6, inventory, receipt);
  till.Sell(sandwich, 5, inventory, receipt);
  receipt.Display();
  Write "Total: ", till.Total();
EndAlgorithm
